workflow.input_script:
function toArray(value) {
  if (Array.isArray(value)) return value;
  if (value === undefined || value === null || value === '') return [];
  return [value];
}

var owners = toArray(input.owner);
var names = toArray(input.name);
if (owners.length === 0 || names.length === 0) {
  throw new Error('owner and name are required');
}
if (owners.length !== names.length) {
  throw new Error('owner and name must contain the same number of values');
}

var repoIds = [];
var seen = {};
for (var i = 0; i < owners.length; i++) {
  var owner = String(owners[i] === undefined || owners[i] === null ? '' : owners[i]).trim();
  var name = String(names[i] === undefined || names[i] === null ? '' : names[i]).trim();
  if (!owner || !name) {
    throw new Error('owner and name values must not be empty');
  }
  var repoId = owner.replace(/\//g, ':') + '/' + name;
  if (!seen[repoId]) {
    seen[repoId] = true;
    repoIds.push(repoId);
  }
}

var flag = input.flag === undefined || input.flag === null ? '' : String(input.flag).trim();
({ repo_ids: repoIds, flag: flag })

workflow.output_script:
var rows = results.line_counts || [];
var seen = {};
var covered = 0;
var partial = 0;
var uncovered = 0;

for (var i = 0; i < rows.length; i++) {
  var row = rows[i] || {};
  var repoId = row.repo_id ? String(row.repo_id) : '';
  if (!repoId || seen[repoId]) continue;
  seen[repoId] = true;
  covered += Number(row.hits) || 0;
  partial += Number(row.partials) || 0;
  uncovered += Number(row.misses) || 0;
}

if (covered === 0 && partial === 0 && uncovered === 0) {
  ({ error: input.flag ? 'No line coverage data for ' + input.flag : 'No line coverage data found' });
} else {
  var total = covered + partial + uncovered;
  ({
    type: 'doughnut',
    label: input.flag ? 'Line Coverage Breakdown — ' + input.flag : 'Line Coverage Breakdown',
    description: '<b>Covered</b> — lines executed by tests.<br><b>Partial</b> — partly executed (for example, a branch was not taken).<br><b>Uncovered</b> — no test execution.<br>Total: ' + total + ' lines.<br><br>Percentages are weighted by line count, so larger repositories contribute more.',
    data: {
      labels: ['Covered', 'Partial', 'Uncovered'],
      datasets: [{
        data: [covered, partial, uncovered],
        backgroundColor: ['#3E8635', '#F0AB00', '#A30000'],
        borderColor: ['#1E4F18', '#B08000', '#7D1007']
      }]
    }
  });
}

tests.assert_script:
if (!output || output.type !== 'doughnut') throw new Error('expected doughnut response');
if (!output.data || !output.data.datasets || output.data.datasets.length !== 1) throw new Error('missing dataset');
var values = output.data.datasets[0].data;
if (!values || values.length !== 3) throw new Error('expected three line totals');
if (Number(values[0]) + Number(values[1]) + Number(values[2]) <= 0) throw new Error('expected non-zero line total');

if (!output || output.type !== 'doughnut') throw new Error('expected doughnut response');
if (output.label.indexOf('unit-tests') === -1) throw new Error('flag missing from label');
var values = output.data.datasets[0].data;
if (Number(values[0]) + Number(values[1]) + Number(values[2]) <= 0) throw new Error('expected non-zero flag line total');
